import { type ReactNode, useEffect, useMemo, useState } from 'react'
import { Activity, BadgeEuro, Ban, Bell, BookOpenCheck, CheckCircle2, CircleDollarSign, Copy, CreditCard, Download, Eye, EyeOff, Facebook, Image as ImageIcon, KeyRound, Mail, Megaphone, Plus, Power, RefreshCw, Save, Search, Settings2, ShieldCheck, Sparkles, Store, TicketCheck, Trash2, UsersRound, WalletCards, WandSparkles } from 'lucide-react'
import { supabase } from '../lib/supabase'
import type { AdminAuditLog, CustomerProfile, CustomerSubscription, LicenseCodeRow, NotificationOutbox, SalesOrder, SalesPlan, SalesSettings } from '../types'

type View = 'overview'|'customers'|'sales'|'licenses'|'plans'|'system'|'messages'|'audit'
type RestaurantLite = { id:string; owner_id:string; name:string; city:string|null; created_at:string }
type PostLite = { id:string; restaurant_id:string; status:string; created_at:string }
type CreativeLite = { id:string; user_id:string; restaurant_id:string; created_at:string }
type PaymentEvent={id:string;event_type:string;order_id:string|null;status:string;error_message:string|null;created_at:string;processed_at:string|null}
type DiscoveryHealth={mode:string;live_search_volume:boolean;external_provider_configured:boolean;external_provider?:string;external_terms?:number;external_latest_at?:string|null;total_terms:number;active_terms:number;stale_7d:number;stale_30d:number;latest_verified_at:string|null;oldest_verified_at:string|null;sources:Record<string,number>;platforms:Record<string,number>;categories:Record<string,number>;performance_samples:number;performance_restaurants:number;learned_terms:number;learning_samples:number;last_learned_at:string|null;last_sync_run:Record<string,unknown>|null;last_learning_run:Record<string,unknown>|null}
type DiscoverySyncRun={id:string;source:string;mode:string;status:'started'|'success'|'skipped'|'failed';terms_seen:number;terms_updated:number;started_at:string;finished_at:string|null;error_message:string|null;metadata:Record<string,unknown>}
type DiscoveryCandidate={id:string;provider:string;seed_query:string;query:string;geo:string;trend_type:'rising'|'top';trend_value:string|null;extracted_value:number;relevance_score:number;status:'pending'|'approved'|'rejected';first_seen_at:string;last_seen_at:string;decided_at:string|null;metadata:Record<string,unknown>}
type DiscoverySeed={id:string;geo:string;query:string;active:boolean;sort_order:number;created_at:string;updated_at:string}
type DiscoveryEngineConfig={provider_enabled:boolean;per_sync_call_limit:number;daily_call_limit:number;candidate_seed_limit:number;daily_calls_used:number;updated_at:string|null;seeds:DiscoverySeed[]}
type AppControls = {
  id:number; app_name:string; app_version:string; maintenance_mode:boolean; maintenance_message:string|null
  sales_open:boolean; signup_open:boolean; ai_images_enabled:boolean; announcement_enabled:boolean
  announcement_text:string|null; announcement_tone:'info'|'success'|'warning'; support_whatsapp:string|null; updated_at:string
}
type SaleForm={userId:string;planId:string;days:string;amount:string;paymentMethod:string;note:string}
type LicenseForm={planId:string;email:string;days:string;amount:string;paymentMethod:string;note:string}
type Generated={id:string;code:string;plan:string;assigned_email:string|null}

const methods=[['manual','Ručno / ostalo'],['bank_transfer','Uplata na račun'],['invoice','Predračun / faktura'],['paypal','PayPal'],['card','Kartica'],['cash','Keš']] as const
const freshSale:SaleForm={userId:'',planId:'',days:'',amount:'',paymentMethod:'manual',note:''}
const freshLicense:LicenseForm={planId:'',email:'',days:'',amount:'',paymentMethod:'manual',note:''}
const defaultControls:AppControls={id:1,app_name:'Restaurant Autopilot',app_version:'1.0',maintenance_mode:false,maintenance_message:null,sales_open:true,signup_open:true,ai_images_enabled:true,announcement_enabled:false,announcement_text:null,announcement_tone:'info',support_whatsapp:null,updated_at:''}
const defaultDiscoveryEngine:DiscoveryEngineConfig={provider_enabled:true,per_sync_call_limit:18,daily_call_limit:60,candidate_seed_limit:8,daily_calls_used:0,updated_at:null,seeds:[]}

export function OwnerControl({onCloseApp,setNotice}:{onCloseApp?:()=>void;setNotice:(v:string)=>void}){
  const [view,setView]=useState<View>('overview')
  const [profiles,setProfiles]=useState<CustomerProfile[]>([]),[restaurants,setRestaurants]=useState<RestaurantLite[]>([]),[plans,setPlans]=useState<SalesPlan[]>([])
  const [subs,setSubs]=useState<CustomerSubscription[]>([]),[orders,setOrders]=useState<SalesOrder[]>([]),[licenses,setLicenses]=useState<LicenseCodeRow[]>([])
  const [settings,setSettings]=useState<SalesSettings|null>(null),[controls,setControls]=useState<AppControls>(defaultControls),[outbox,setOutbox]=useState<NotificationOutbox[]>([]),[audit,setAudit]=useState<AdminAuditLog[]>([]),[paymentEvents,setPaymentEvents]=useState<PaymentEvent[]>([]),[discoveryRuns,setDiscoveryRuns]=useState<DiscoverySyncRun[]>([]),[discoveryCandidates,setDiscoveryCandidates]=useState<DiscoveryCandidate[]>([]),[discoveryEngine,setDiscoveryEngine]=useState<DiscoveryEngineConfig>(defaultDiscoveryEngine)
  const [posts,setPosts]=useState<PostLite[]>([]),[creative,setCreative]=useState<CreativeLite[]>([]),[aiConfigured,setAiConfigured]=useState(false),[emailConfigured,setEmailConfigured]=useState(false),[metaConfigured,setMetaConfigured]=useState(false),[stripeConfigured,setStripeConfigured]=useState(false),[stripeMode,setStripeMode]=useState<'test'|'live'|'unknown'>('unknown'),[discoveryHealth,setDiscoveryHealth]=useState<DiscoveryHealth|null>(null)
  const [working,setWorking]=useState(false),[search,setSearch]=useState(''),[sale,setSale]=useState<SaleForm>(freshSale),[license,setLicense]=useState<LicenseForm>(freshLicense),[generated,setGenerated]=useState<Generated|null>(null)
  const [noteTarget,setNoteTarget]=useState<CustomerProfile|null>(null),[detailTarget,setDetailTarget]=useState<CustomerProfile|null>(null),[noteSubject,setNoteSubject]=useState('Restaurant Autopilot'),[noteBody,setNoteBody]=useState(''),[aiKey,setAiKey]=useState(''),[emailKey,setEmailKey]=useState(''),[metaAppId,setMetaAppId]=useState(''),[metaAppSecret,setMetaAppSecret]=useState(''),[stripeSecretKey,setStripeSecretKey]=useState(''),[stripeWebhookSecret,setStripeWebhookSecret]=useState(''),[discoveryProviderKey,setDiscoveryProviderKey]=useState(''),[newDiscoverySeed,setNewDiscoverySeed]=useState({query:'',geo:'RS'})

  useEffect(()=>{void load(true)},[])

  async function load(housekeeping=false){
    setWorking(true)
    if(housekeeping) await supabase.rpc('admin_housekeeping')
    const [a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v]=await Promise.all([
      supabase.from('customer_profiles').select('*').order('created_at',{ascending:false}),
      supabase.from('restaurants').select('id,owner_id,name,city,created_at').order('created_at',{ascending:false}),
      supabase.from('sales_plans').select('*').order('sort_order'),
      supabase.from('customer_subscriptions').select('*, sales_plans(*)').order('created_at',{ascending:false}),
      supabase.from('sales_orders').select('*, sales_plans(*)').order('created_at',{ascending:false}),
      supabase.from('license_codes').select('*, sales_plans(*)').order('created_at',{ascending:false}).limit(250),
      supabase.from('sales_settings').select('*').eq('id',1).maybeSingle(),
      supabase.from('notification_outbox').select('*').order('created_at',{ascending:false}).limit(250),
      supabase.from('admin_audit_log').select('*').order('created_at',{ascending:false}).limit(300),
      supabase.from('app_controls').select('*').eq('id',1).maybeSingle(),
      supabase.from('posts').select('id,restaurant_id,status,created_at').order('created_at',{ascending:false}).limit(5000),
      supabase.from('creative_assets').select('id,user_id,restaurant_id,created_at').order('created_at',{ascending:false}).limit(5000),
      supabase.rpc('admin_ai_provider_status'),
      supabase.rpc('admin_email_provider_status'),
      supabase.rpc('admin_meta_provider_status'),
      supabase.rpc('admin_stripe_provider_status'),
      supabase.rpc('admin_payment_event_feed',{p_limit:50}),
      supabase.functions.invoke('checkout-order',{body:{action:'status'}}),
      supabase.rpc('admin_discovery_health'),
      supabase.rpc('admin_discovery_sync_feed',{p_limit:12}),
      supabase.rpc('admin_discovery_candidate_feed',{p_limit:30}),
      supabase.rpc('admin_discovery_engine_config'),
    ])
    const err=a.error||b.error||c.error||d.error||e.error||f.error||g.error||h.error||i.error||j.error||k.error||l.error||m.error||n.error||o.error||p.error||q.error||r.error||s.error||t.error||u.error||v.error
    if(err)setNotice(err.message)
    setProfiles((a.data||[]) as CustomerProfile[]);setRestaurants((b.data||[]) as RestaurantLite[]);setPlans((c.data||[]) as SalesPlan[]);setSubs((d.data||[]) as CustomerSubscription[]);setOrders((e.data||[]) as SalesOrder[]);setLicenses((f.data||[]) as LicenseCodeRow[]);setSettings((g.data||null) as SalesSettings|null);setOutbox((h.data||[]) as NotificationOutbox[]);setAudit((i.data||[]) as AdminAuditLog[]);setControls((j.data||defaultControls) as AppControls);setPosts((k.data||[]) as PostLite[]);setCreative((l.data||[]) as CreativeLite[]);setAiConfigured(Boolean((m.data as any)?.configured));setEmailConfigured(Boolean((n.data as any)?.configured));setMetaConfigured(Boolean((o.data as any)?.configured));setStripeConfigured(Boolean((p.data as any)?.configured));setPaymentEvents((q.data||[]) as PaymentEvent[]);setStripeMode(((r.data as any)?.mode||'unknown') as 'test'|'live'|'unknown');setDiscoveryHealth((s.data||null) as DiscoveryHealth|null);setDiscoveryRuns((t.data||[]) as DiscoverySyncRun[]);setDiscoveryCandidates((u.data||[]) as DiscoveryCandidate[]);setDiscoveryEngine((v.data||defaultDiscoveryEngine) as DiscoveryEngineConfig);setWorking(false)
  }

  const active=useMemo(()=>subs.filter(s=>['active','trialing'].includes(s.status)&&(!s.expires_at||new Date(s.expires_at).getTime()>Date.now())),[subs])
  const pending=useMemo(()=>orders.filter(o=>o.status==='pending'),[orders])
  const revenue=useMemo(()=>orders.filter(o=>o.status==='paid').reduce((n,o)=>n+Number(o.amount||0),0),[orders])
  const monthRevenue=useMemo(()=>orders.filter(o=>o.status==='paid'&&sameMonth(o.paid_at||o.created_at,new Date())).reduce((n,o)=>n+Number(o.amount||0),0),[orders])
  const monthPosts=useMemo(()=>posts.filter(p=>sameMonth(p.created_at,new Date())).length,[posts])
  const monthAi=useMemo(()=>creative.filter(p=>sameMonth(p.created_at,new Date())).length,[creative])
  const expiring=useMemo(()=>active.filter(s=>s.expires_at&&daysTo(s.expires_at)<=7&&daysTo(s.expires_at)>=0),[active])
  const queued=useMemo(()=>outbox.filter(x=>x.delivery_status==='queued'),[outbox])
  const failedOutbox=useMemo(()=>outbox.filter(x=>x.delivery_status==='failed'),[outbox])
  const profileByUser=useMemo(()=>new Map(profiles.map(p=>[p.user_id,p])),[profiles])
  const subByUser=useMemo(()=>{const map=new Map<string,CustomerSubscription>();subs.forEach(s=>{if(!map.has(s.user_id))map.set(s.user_id,s)});return map},[subs])
  const restaurantsByUser=useMemo(()=>{const map=new Map<string,RestaurantLite[]>();restaurants.forEach(r=>map.set(r.owner_id,[...(map.get(r.owner_id)||[]),r]));return map},[restaurants])
  const ownerByRestaurant=useMemo(()=>new Map(restaurants.map(r=>[r.id,r.owner_id])),[restaurants])
  const postCountByUser=useMemo(()=>{const map=new Map<string,number>();posts.forEach(p=>{const u=ownerByRestaurant.get(p.restaurant_id);if(u)map.set(u,(map.get(u)||0)+1)});return map},[posts,ownerByRestaurant])
  const aiCountByUser=useMemo(()=>{const map=new Map<string,number>();creative.forEach(x=>map.set(x.user_id,(map.get(x.user_id)||0)+1));return map},[creative])
  const customers=useMemo(()=>{const q=search.toLowerCase().trim();return q?profiles.filter(p=>`${p.email} ${p.full_name||''} ${p.company||''} ${(restaurantsByUser.get(p.user_id)||[]).map(r=>r.name).join(' ')}`.toLowerCase().includes(q)):profiles},[profiles,search,restaurantsByUser])
  const detailSub=detailTarget?subByUser.get(detailTarget.user_id):undefined
  const detailRestaurants=detailTarget?(restaurantsByUser.get(detailTarget.user_id)||[]):[]
  const detailOrders=detailTarget?orders.filter(o=>o.user_id===detailTarget.user_id):[]
  const detailPaid=detailOrders.filter(o=>o.status==='paid').reduce((n,o)=>n+Number(o.amount||0),0)
  const detailPosts=detailTarget?(postCountByUser.get(detailTarget.user_id)||0):0
  const detailAi=detailTarget?(aiCountByUser.get(detailTarget.user_id)||0):0

  async function paid(o:SalesOrder){setWorking(true);const{error}=await supabase.rpc('admin_mark_order_paid',{p_order_id:o.id,p_admin_note:'Potvrđeno iz OWNER panela'});if(error)setNotice(error.message);else{await tryDispatchOwnerQueue();setNotice(`${o.order_number}: uplata potvrđena i pristup aktiviran.`);await load()}setWorking(false)}
  async function cancel(o:SalesOrder){if(!confirm(`Otkaži ${o.order_number}?`))return;const{error}=await supabase.from('sales_orders').update({status:'cancelled',admin_note:'Otkazano iz OWNER panela'}).eq('id',o.id);if(error)setNotice(error.message);else{setNotice('Narudžbina je otkazana.');await load()}}
  async function refund(o:SalesOrder){if(!confirm(`Refund ${o.order_number} i suspenduj pristup?`))return;setWorking(true);const{error}=await supabase.rpc('admin_refund_order',{p_order_id:o.id,p_suspend_access:true,p_note:'Refund iz OWNER panela'});if(error)setNotice(error.message);else{setNotice('Refund je evidentiran i pristup zatvoren.');await load()}setWorking(false)}
  async function grant(){if(!sale.userId||!sale.planId){setNotice('Izaberi kupca i paket.');return}setWorking(true);const{error}=await supabase.rpc('admin_grant_access',{p_user_id:sale.userId,p_plan_id:sale.planId,p_days:sale.days?Number(sale.days):null,p_payment_method:sale.paymentMethod,p_amount:sale.amount?Number(sale.amount):null,p_note:sale.note||null});if(error)setNotice(error.message);else{setNotice('Kupac je aktiviran i prodaja evidentirana.');setSale(freshSale);await load()}setWorking(false)}
  async function makeLicense(){if(!license.planId){setNotice('Izaberi paket.');return}setWorking(true);const{data,error}=await supabase.rpc('admin_create_license_code',{p_plan_id:license.planId,p_duration_days:license.days?Number(license.days):null,p_assigned_email:license.email||null,p_sale_amount:license.amount?Number(license.amount):null,p_payment_method:license.paymentMethod,p_note:license.note||null});if(error)setNotice(error.message);else{setGenerated(data as Generated);setNotice('Licenca je napravljena. Puni kod kopiraj sada.');setLicense(freshLicense);await load()}setWorking(false)}
  async function extend(s:CustomerSubscription,days:number){const d=s.expires_at&&new Date(s.expires_at).getTime()>Date.now()?new Date(s.expires_at):new Date();d.setDate(d.getDate()+days);const{error}=await supabase.from('customer_subscriptions').update({expires_at:d.toISOString(),status:'active'}).eq('id',s.id);if(error)setNotice(error.message);else{setNotice(`Pristup produžen za ${days} dana.`);await load()}}
  async function setSubStatus(s:CustomerSubscription,status:CustomerSubscription['status']){const{error}=await supabase.from('customer_subscriptions').update({status}).eq('id',s.id);if(error)setNotice(error.message);else{setNotice(status==='suspended'?'Kupac je suspendovan.':'Kupac je ponovo aktivan.');await load()}}
  async function revoke(x:LicenseCodeRow){if(!confirm('Opozovi ovu licencu?'))return;const{error}=await supabase.from('license_codes').update({status:'revoked'}).eq('id',x.id);if(error)setNotice(error.message);else await load()}
  async function savePlan(p:SalesPlan,patch:{price:number;monthly_generation_limit:number;max_restaurants:number;trial_days:number;active:boolean;public:boolean;features:Record<string,unknown>}){const{error}=await supabase.from('sales_plans').update(patch).eq('id',p.id);if(error)setNotice(error.message);else{setNotice(`${p.name}: paket i funkcije su sačuvani.`);await load()}}
  async function saveSystem(){setWorking(true);const{error}=await supabase.from('app_controls').update({...controls,updated_at:new Date().toISOString()}).eq('id',1);if(error)setNotice(error.message);else{setNotice('Globalna kontrola aplikacije je sačuvana.');await load()}setWorking(false)}
  async function saveSales(){if(!settings)return;if(settings.allow_card&&(!stripeConfigured||stripeMode!=='live')){setNotice(stripeMode==='test'?'Kartice nisu puštene: Stripe je još u TEST modu. Unesi live ključ i live webhook secret pre uključivanja kupcima.':'Kartice nisu puštene: prvo podesi Stripe provider.');setSettings({...settings,allow_card:false});return}setWorking(true);const{error}=await supabase.from('sales_settings').update(settings).eq('id',1);if(error)setNotice(error.message);else setNotice('Firma, banka i načini prodaje su sačuvani.');setWorking(false)}
  async function saveAiKey(){if(!aiKey.trim()){setNotice('Unesi OpenAI API ključ.');return}setWorking(true);const{error}=await supabase.rpc('admin_set_ai_provider_key',{p_key:aiKey.trim()});if(error)setNotice(error.message);else{setAiKey('');setAiConfigured(true);setNotice('AI provider je aktiviran server-side. Ključ se ne prikazuje kupcima.')}setWorking(false)}
  async function saveEmailKey(){if(!emailKey.trim()){setNotice('Unesi Resend API ključ.');return}setWorking(true);const{error}=await supabase.rpc('admin_set_email_provider_key',{p_key:emailKey.trim()});if(error)setNotice(error.message);else{setEmailKey('');setEmailConfigured(true);setNotice('Email provider je aktiviran server-side. Sada podesi Email from adresu i možeš slati Outbox.')}setWorking(false)}
  async function saveMetaProvider(){if(!metaAppId.trim()||!metaAppSecret.trim()){setNotice('Unesi Meta App ID i App Secret.');return}setWorking(true);const{error}=await supabase.rpc('admin_set_meta_provider',{p_app_id:metaAppId.trim(),p_app_secret:metaAppSecret.trim()});if(error)setNotice(error.message);else{setMetaAppId('');setMetaAppSecret('');setMetaConfigured(true);setNotice('Meta provider je aktiviran server-side. Restorani sada mogu da pokrenu Facebook / Instagram Connect.')}setWorking(false)}
  async function saveStripeProvider(){if(!stripeSecretKey.trim()||!stripeWebhookSecret.trim()){setNotice('Unesi Stripe Secret Key i Webhook Secret.');return}setWorking(true);const{error}=await supabase.rpc('admin_set_stripe_provider',{p_secret_key:stripeSecretKey.trim(),p_webhook_secret:stripeWebhookSecret.trim()});if(error)setNotice(error.message);else{setStripeSecretKey('');setStripeWebhookSecret('');setStripeConfigured(true);setNotice('Stripe provider je aktiviran server-side. Kartice možeš uključiti u Prodavac i naplata podešavanjima.')}setWorking(false)}
  async function refreshDiscoveryLearning(){setWorking(true);const{data,error}=await supabase.rpc('admin_refresh_discovery_learning');if(error)setNotice(error.message);else{const learned=Number((data as any)?.learned_terms||0),samples=Number((data as any)?.term_observations||0);setNotice(learned?`Discovery learning: ${learned} termina preračunato iz ${samples} term-observacija.`:'Discovery learning je preračunat, ali još nema IG/FB performance podataka vezanih za bank termine.');await load()}setWorking(false)}
  async function saveDiscoveryProvider(){if(discoveryProviderKey.trim().length<20){setNotice('Unesi validan SerpApi API ključ.');return}setWorking(true);const{error}=await supabase.rpc('admin_set_discovery_provider_key',{p_key:discoveryProviderKey.trim()});if(error)setNotice(error.message);else{setDiscoveryProviderKey('');setNotice('Google Trends provider je aktiviran server-side. Ključ je sačuvan u Vault-u.');await load()}setWorking(false)}
  async function syncExternalDiscovery(){if(!discoveryHealth?.external_provider_configured){setNotice('Prvo podesi SerpApi ključ za Google Trends.');return}setWorking(true);const{data,error}=await supabase.functions.invoke('discovery-sync',{body:{action:'sync_now'}});if(error||data?.error)setNotice(data?.error||error?.message||'Discovery sync nije uspeo.');else{const updated=Number(data?.updated||0),calls=Number(data?.api_calls||0),failed=Number(data?.failed_batches||0);setNotice(`Google Trends sync: osveženo ${updated} termina · ${calls} API poziva${failed?` · ${failed} batch grešaka`:''}.`);await load()}setWorking(false)}
  async function decideDiscoveryCandidate(item:DiscoveryCandidate,status:'approved'|'rejected'|'pending'){setWorking(true);const{error}=await supabase.rpc('admin_set_discovery_candidate_status',{p_id:item.id,p_status:status});if(error)setNotice(error.message);else{setNotice(status==='approved'?'Trend „'+item.query+'“ je odobren za SEO i AUTO WEEK trend signal.':status==='rejected'?'Trend „'+item.query+'“ je odbijen.':'Trend „'+item.query+'“ je vraćen na čekanje.');await load()}setWorking(false)}

  async function saveDiscoveryEngineSettings(){
    setWorking(true)
    const{data,error}=await supabase.rpc('admin_update_discovery_engine_settings',{
      p_provider_enabled:discoveryEngine.provider_enabled,
      p_per_sync_call_limit:Number(discoveryEngine.per_sync_call_limit),
      p_daily_call_limit:Number(discoveryEngine.daily_call_limit),
      p_candidate_seed_limit:Number(discoveryEngine.candidate_seed_limit),
    })
    if(error)setNotice(error.message)
    else{setDiscoveryEngine((data||discoveryEngine) as DiscoveryEngineConfig);setNotice('Discovery Engine budžet i provider kontrola su sačuvani.')}
    setWorking(false)
  }
  function patchDiscoverySeed(id:string,patch:Partial<DiscoverySeed>){setDiscoveryEngine(current=>({...current,seeds:current.seeds.map(seed=>seed.id===id?{...seed,...patch}:seed)}))}
  async function saveDiscoverySeed(seed:DiscoverySeed){
    setWorking(true)
    const{error}=await supabase.rpc('admin_upsert_discovery_seed',{p_id:seed.id,p_query:seed.query.trim(),p_geo:seed.geo,p_active:seed.active,p_sort_order:Number(seed.sort_order)})
    if(error)setNotice(error.message);else{setNotice('Discovery seed „'+seed.query+'“ je sačuvan.');await load()}
    setWorking(false)
  }
  async function addDiscoverySeed(){
    const query=newDiscoverySeed.query.trim()
    if(query.length<2){setNotice('Upiši seed termin.');return}
    const nextOrder=(discoveryEngine.seeds.reduce((max,seed)=>Math.max(max,Number(seed.sort_order||0)),0)||0)+10
    setWorking(true)
    const{error}=await supabase.rpc('admin_upsert_discovery_seed',{p_id:null,p_query:query,p_geo:newDiscoverySeed.geo,p_active:true,p_sort_order:nextOrder})
    if(error)setNotice(error.message);else{setNewDiscoverySeed({query:'',geo:'RS'});setNotice('Novi Discovery seed je dodat.');await load()}
    setWorking(false)
  }
  async function deleteDiscoverySeed(seed:DiscoverySeed){
    setWorking(true)
    const{error}=await supabase.rpc('admin_delete_discovery_seed',{p_id:seed.id})
    if(error)setNotice(error.message);else{setNotice('Seed „'+seed.query+'“ je obrisan.');await load()}
    setWorking(false)
  }
  async function tryDispatchOwnerQueue(){if(!emailConfigured||!settings?.email_from)return;await supabase.functions.invoke('email-dispatch',{body:{action:'send_queue',limit:25}}).catch(()=>null)}
  async function dispatchEmails(){setWorking(true);const{data,error}=await supabase.functions.invoke('email-dispatch',{body:{action:'send_queue',limit:25}});if(error)setNotice(error.message);else if(data?.error)setNotice(data.error);else{setNotice(`Email Outbox: poslato ${data?.sent||0}, neuspešno ${data?.failed||0}.`);await load()}setWorking(false)}
  async function retryFailedEmails(){setWorking(true);const{data,error}=await supabase.functions.invoke('email-dispatch',{body:{action:'retry_failed'}});if(error)setNotice(error.message);else if(data?.error)setNotice(data.error);else{setNotice('Neuspele poruke su vraćene u red za slanje.');await load()}setWorking(false)}
  async function sendNote(){if(!noteTarget||!noteSubject.trim()||!noteBody.trim()){setNotice('Upiši naslov i poruku.');return}setWorking(true);const{error}=await supabase.rpc('admin_send_note',{p_user_id:noteTarget.user_id,p_subject:noteSubject.trim(),p_body:noteBody.trim()});if(error)setNotice(error.message);else{await tryDispatchOwnerQueue();setNotice(emailConfigured&&settings?.email_from?'Poruka je poslata kupcu i sačuvana u Outbox-u.':'Poruka je dodata kupcu i u Outbox.');setNoteTarget(null);setNoteBody('');await load()}setWorking(false)}
  async function markOut(x:NotificationOutbox,status:'sent'|'dismissed'){const patch=status==='sent'?{delivery_status:'sent',sent_at:new Date().toISOString()}:{delivery_status:'dismissed'};const{error}=await supabase.from('notification_outbox').update(patch).eq('id',x.id);if(error)setNotice(error.message);else await load()}
  function copy(v:string){navigator.clipboard.writeText(v).then(()=>setNotice('Kopirano.')).catch(()=>setNotice('Browser nije dozvolio kopiranje.'))}
  function exportSales(){downloadCsv('restaurant-autopilot-prodaja.csv',[['narudzbina','datum','kupac','paket','status','nacin','iznos','valuta','referenca'],...orders.map(o=>[o.order_number,o.created_at,profileByUser.get(o.user_id)?.email||o.user_id,o.sales_plans?.name||'',o.status,o.payment_method,String(o.amount),o.currency,o.payment_reference||''])]);setNotice('Prodaja je izvezena u CSV.')}
  function exportCustomers(){downloadCsv('restaurant-autopilot-kupci.csv',[['email','ime','firma','restorani','paket','status','vazi_do','objave','ai_slike'],...profiles.map(p=>{const s=subByUser.get(p.user_id);return[p.email,p.full_name||'',p.company||'',String((restaurantsByUser.get(p.user_id)||[]).length),s?.sales_plans?.name||'',s?.status||'',s?.expires_at||'',String(postCountByUser.get(p.user_id)||0),String(aiCountByUser.get(p.user_id)||0)]})]);setNotice('Kupci su izvezeni u CSV.')}
  function backup(){const payload={exported_at:new Date().toISOString(),app_controls:controls,sales_settings:settings,plans,profiles,restaurants,subscriptions:subs,orders,licenses,creative_assets:creative,posts_summary:posts,outbox,audit};downloadText(`restaurant-autopilot-backup-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(payload,null,2),'application/json');setNotice('OWNER backup snapshot je preuzet.')}

  return <div className="superadmin-page superadmin-v2 owner-control-v3">
    <header className="admin-topbar"><div><span className="admin-shield"><ShieldCheck size={21}/></span><div><p>RESTAURANT AUTOPILOT</p><h1>OWNER Control Center</h1></div></div><div className="admin-top-actions"><span className={`admin-live ${controls.maintenance_mode?'owner-offline':''}`}><i/> {controls.maintenance_mode?'MAINTENANCE':'SYSTEM ONLINE'}</span><button className="secondary" onClick={backup}><Download size={15}/> Backup</button><button className="secondary" onClick={()=>void load(true)} disabled={working}><RefreshCw size={15}/> Osveži</button>{onCloseApp&&<button className="secondary" onClick={onCloseApp}>Nazad u app</button>}</div></header>
    <nav className="admin-tabs owner-tabs"><Tab a={view==='overview'} f={()=>setView('overview')} i={<Activity size={16}/>} l="Pregled"/><Tab a={view==='customers'} f={()=>setView('customers')} i={<UsersRound size={16}/>} l="Kupci"/><Tab a={view==='sales'} f={()=>setView('sales')} i={<WalletCards size={16}/>} l="Prodaja" c={pending.length}/><Tab a={view==='licenses'} f={()=>setView('licenses')} i={<KeyRound size={16}/>} l="Licence"/><Tab a={view==='plans'} f={()=>setView('plans')} i={<BadgeEuro size={16}/>} l="Paketi"/><Tab a={view==='system'} f={()=>setView('system')} i={<Settings2 size={16}/>} l="Sistem"/><Tab a={view==='messages'} f={()=>setView('messages')} i={<Bell size={16}/>} l="Poruke" c={queued.length}/><Tab a={view==='audit'} f={()=>setView('audit')} i={<BookOpenCheck size={16}/>} l="Audit"/></nav>

    {view==='overview'&&<><section className="admin-metrics owner-metrics"><Metric i={<UsersRound size={18}/>} l="Registrovani" v={profiles.length}/><Metric i={<Store size={18}/>} l="Restorani" v={restaurants.length}/><Metric i={<TicketCheck size={18}/>} l="Aktivni paketi" v={active.length}/><Metric i={<CircleDollarSign size={18}/>} l="Ovaj mesec" v={`${monthRevenue.toFixed(0)} €`}/><Metric i={<Sparkles size={18}/>} l="Objave / mes" v={monthPosts}/><Metric i={<ImageIcon size={18}/>} l="AI slike / mes" v={monthAi}/></section>
      <section className="owner-health-grid"><HealthCard icon={<Power size={18}/>} title="Aplikacija" value={controls.maintenance_mode?'Maintenance':'Online'} ok={!controls.maintenance_mode} detail={`v${controls.app_version}`}/><HealthCard icon={<WalletCards size={18}/>} title="Prodaja" value={controls.sales_open?'Otvorena':'Zatvorena'} ok={controls.sales_open} detail={`${pending.length} čeka uplatu`}/><HealthCard icon={<WandSparkles size={18}/>} title="AI Food Image" value={aiConfigured&&controls.ai_images_enabled?'Spreman':aiConfigured?'Pauziran':'Nije podešen'} ok={aiConfigured&&controls.ai_images_enabled} detail={`${monthAi} generisano ovog meseca`}/><HealthCard icon={<Bell size={18}/>} title="Outbox" value={`${queued.length} čeka`} ok={queued.length===0} detail={`${outbox.length} poruka ukupno`}/><HealthCard icon={<Search size={18}/>} title="Discovery Bank" value={discoveryHealth?`${discoveryHealth.active_terms} termina`:'Čitam…'} ok={Boolean(discoveryHealth&&discoveryHealth.stale_30d===0)} detail={discoveryHealth?`${discoveryHealth.learned_terms||0} uči iz rezultata · ${discoveryHealth.stale_7d} starije od 7 dana`:'Proveravam svežinu podataka'}/></section>
      {expiring.length>0&&<section className="admin-alert-strip"><Bell size={18}/><div><strong>{expiring.length} paketa ističe u narednih 7 dana</strong><span>Otvori Kupci i produži pristup ili pošalji podsetnik.</span></div><button onClick={()=>setView('customers')}>Otvori kupce</button></section>}
      <div className="admin-overview-grid"><QuickSale profiles={profiles} plans={plans} form={sale} setForm={setSale} go={grant} working={working}/><LicenseMaker plans={plans} form={license} setForm={setLicense} go={makeLicense} generated={generated} copy={copy} working={working}/></div>
      <section className="admin-panel"><Head e="POSLEDNJE NARUDŽBINE" t="Prodajni tok" side={<button className="secondary" onClick={exportSales}><Download size={14}/> CSV prodaje</button>}/><Orders rows={orders.slice(0,8)} profiles={profiles} paid={paid} cancel={cancel} refund={refund} working={working}/></section></>}

    {view==='customers'&&<section className="admin-panel"><div className="admin-panel-head admin-customers-head"><div><p className="eyebrow">KUPCI I KORIŠĆENJE</p><h2>Svi nalozi pod tvojom kontrolom</h2></div><div className="admin-head-actions"><button className="secondary" onClick={exportCustomers}><Download size={14}/> CSV</button><div className="admin-search"><Search size={15}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Email, restoran, firma..."/></div></div></div><div className="admin-table customer-table owner-customer-table"><div className="admin-table-head"><span>Kupac</span><span>Lokacije</span><span>Paket</span><span>Korišćenje</span><span>Važi do</span><span>Kontrola</span></div>{customers.length?customers.map(p=>{const s=subByUser.get(p.user_id),rs=restaurantsByUser.get(p.user_id)||[],pc=postCountByUser.get(p.user_id)||0,ac=aiCountByUser.get(p.user_id)||0;return <div className="admin-table-row" key={p.user_id}><div><strong>{p.full_name||p.email}</strong><small>{p.email}{p.company?` · ${p.company}`:''}</small></div><div><strong>{rs.length}</strong><small>{rs.map(r=>r.name).slice(0,2).join(' · ')||'nije dodat restoran'}</small></div><div>{s?<><span className={`status ${s.status}`}>{s.status}</span><small>{s.sales_plans?.name||'custom'}</small></>:<span className="status pending">bez paketa</span>}</div><div className="owner-usage-mini"><span><Sparkles size={12}/>{pc} objava</span><span><ImageIcon size={12}/>{ac} AI slika</span></div><div><strong>{s?.expires_at?new Date(s.expires_at).toLocaleDateString('sr-RS'):s?'bez isteka':'—'}</strong>{s?.expires_at&&daysTo(s.expires_at)<=7&&daysTo(s.expires_at)>=0?<small className="expires-soon">još {daysTo(s.expires_at)} dana</small>:null}</div><div className="admin-row-actions"><button onClick={()=>setDetailTarget(p)}><Eye size={13}/> Detalji</button><button onClick={()=>{setNoteTarget(p);setNoteBody('')}}><Mail size={13}/> Poruka</button>{s&&<><button onClick={()=>void extend(s,30)}>+30d</button><button onClick={()=>void extend(s,365)}>+1g</button>{s.status==='suspended'?<button onClick={()=>void setSubStatus(s,'active')}><CheckCircle2 size={13}/> Aktiviraj</button>:<button className="danger-soft" onClick={()=>void setSubStatus(s,'suspended')}><Ban size={13}/> Suspenduj</button>}</>}</div></div>}):<div className="admin-empty">Još nema kupaca.</div>}</div></section>}

    {view==='sales'&&<div className="owner-sales-stack"><section className="admin-panel"><Head e="PRODAJA" t="Narudžbine, uplate i refundi" side={<div className="admin-head-actions"><span className="admin-counter">{pending.length} čeka</span><button className="secondary" onClick={exportSales}><Download size={14}/> CSV</button></div>}/><Orders rows={orders} profiles={profiles} paid={paid} cancel={cancel} refund={refund} working={working}/></section><section className="admin-panel stripe-event-panel"><Head e="STRIPE WEBHOOK EVENTS" t="Poslednje potvrde plaćanja"/><div className="stripe-event-list">{paymentEvents.length?paymentEvents.map(event=><article className={`stripe-event-row ${event.status}`} key={event.id}><span className="stripe-event-dot"/><div><strong>{event.event_type}</strong><small>{event.order_id?`order · ${event.order_id.slice(0,8)}…`:'bez order reference'}</small>{event.error_message&&<p>{event.error_message}</p>}</div><span className={`stripe-event-status ${event.status}`}>{event.status}</span><time>{new Date(event.created_at).toLocaleString('sr-RS')}</time></article>):<div className="admin-empty">Još nema Stripe webhook događaja.</div>}</div></section></div>}

    {view==='licenses'&&<div className="admin-two-column"><LicenseMaker plans={plans} form={license} setForm={setLicense} go={makeLicense} generated={generated} copy={copy} working={working}/><section className="admin-panel"><Head e="IZDATE LICENCE" t="Kodovi i status"/><div className="license-list">{licenses.length?licenses.map(x=><div className="license-row-admin" key={x.id}><div><strong>•••• {x.code_last4}</strong><span>{x.sales_plans?.name||'Paket'} · {x.assigned_email||'bez email ograničenja'}</span></div><div><span className={`status ${x.status}`}>{x.status}</span><small>{x.use_count}/{x.max_uses} · {x.sale_amount??0} {x.currency}</small></div>{x.status==='active'&&<button className="danger-soft" onClick={()=>void revoke(x)}>Opozovi</button>}</div>):<div className="admin-empty">Nema izdatih licenci.</div>}</div></section></div>}

    {view==='plans'&&<section className="admin-panel"><Head e="PAKETI, CENE I FUNKCIJE" t="Ti određuješ šta kupac dobija"/><div className="owner-plan-grid">{plans.map(p=><PlanEditor key={p.id} plan={p} onSave={savePlan}/>)}</div></section>}

    {view==='system'&&<div className="owner-system-grid"><section className="admin-panel"><Head e="GLOBALNA KONTROLA" t="Aplikacija i prodaja"/><div className="owner-switch-stack"><BigToggle icon={<Power size={18}/>} title="Maintenance mode" detail="Kupcima blokiraš rad dok radiš kritične izmene." value={controls.maintenance_mode} onChange={v=>setControls({...controls,maintenance_mode:v})} danger/><BigToggle icon={<WalletCards size={18}/>} title="Prodaja otvorena" detail="Server-side blokira kreiranje novih narudžbina kada je ugašeno." value={controls.sales_open} onChange={v=>setControls({...controls,sales_open:v})}/><BigToggle icon={<UsersRound size={18}/>} title="Registracije otvorene" detail="Centralni prekidač za nove naloge." value={controls.signup_open} onChange={v=>setControls({...controls,signup_open:v})}/><BigToggle icon={<ImageIcon size={18}/>} title="AI fotografije" detail="Globalno uključuje ili pauzira AI food generation." value={controls.ai_images_enabled} onChange={v=>setControls({...controls,ai_images_enabled:v})}/><BigToggle icon={<Megaphone size={18}/>} title="Obaveštenje u aplikaciji" detail="Prikaži važnu poruku svim korisnicima." value={controls.announcement_enabled} onChange={v=>setControls({...controls,announcement_enabled:v})}/></div><div className="admin-form-grid owner-system-fields"><label>Verzija<input value={controls.app_version} onChange={e=>setControls({...controls,app_version:e.target.value})}/></label><label>WhatsApp podrška<input value={controls.support_whatsapp||''} onChange={e=>setControls({...controls,support_whatsapp:e.target.value})} placeholder="+381..."/></label><label className="span-2">Maintenance poruka<textarea rows={3} value={controls.maintenance_message||''} onChange={e=>setControls({...controls,maintenance_message:e.target.value})} placeholder="Radimo kratko održavanje. Vraćamo se uskoro."/></label><label className="span-2">Globalno obaveštenje<textarea rows={3} value={controls.announcement_text||''} onChange={e=>setControls({...controls,announcement_text:e.target.value})} placeholder="Nova funkcija: Creative AI je dostupan..."/></label><label>Tip poruke<select value={controls.announcement_tone} onChange={e=>setControls({...controls,announcement_tone:e.target.value as AppControls['announcement_tone']})}><option value="info">Info</option><option value="success">Success</option><option value="warning">Warning</option></select></label></div><button className="primary" onClick={saveSystem} disabled={working}><Save size={16}/> Sačuvaj sistem</button></section>
      <section className="admin-panel"><Head e="AI PROVIDER" t="Food Image Engine"/><div className={`owner-ai-status ${aiConfigured&&controls.ai_images_enabled?'ready':''}`}><span><WandSparkles size={23}/></span><div><strong>{aiConfigured?'OpenAI ključ je podešen':'AI ključ nije podešen'}</strong><small>{aiConfigured?(controls.ai_images_enabled?'Generisanje slika je spremno.':'Ključ postoji, ali si AI globalno pauzirao.'):'Unesi ključ jednom. Čuva se server-side u Supabase Vault-u.'}</small></div></div><label className="owner-ai-key">OpenAI API ključ<input type="password" autoComplete="new-password" value={aiKey} onChange={e=>setAiKey(e.target.value)} placeholder={aiConfigured?'Novi sk-… samo ako menjaš postojeći':'sk-…'}/></label><button className="secondary full" onClick={saveAiKey} disabled={working||!aiKey.trim()}><KeyRound size={15}/>{aiConfigured?'Promeni AI ključ':'Aktiviraj AI'}</button><div className="owner-ai-usage"><div><span>Ovog meseca</span><strong>{monthAi}</strong><small>AI food slika</small></div><div><span>Ukupno</span><strong>{creative.length}</strong><small>sačuvanih asseta</small></div></div></section>
      <section className="admin-panel"><Head e="EMAIL PROVIDER" t="Transactional Email"/><div className={`owner-ai-status ${emailConfigured&&settings?.email_from?'ready':''}`}><span><Mail size={23}/></span><div><strong>{emailConfigured?'Resend ključ je podešen':'Email provider nije podešen'}</strong><small>{emailConfigured?(settings?.email_from?`Slanje je spremno sa ${settings.email_from}.`:'Ključ postoji. U prodajnim podešavanjima upiši Email from adresu sa verifikovanog domena.'):'Unesi Resend API ključ jednom. Ključ se čuva server-side u Supabase Vault-u.'}</small></div></div><label className="owner-ai-key">Resend API ključ<input type="password" autoComplete="new-password" value={emailKey} onChange={e=>setEmailKey(e.target.value)} placeholder={emailConfigured?'Novi re_… samo ako menjaš postojeći':'re_…'}/></label><button className="secondary full" onClick={saveEmailKey} disabled={working||!emailKey.trim()}><KeyRound size={15}/>{emailConfigured?'Promeni email ključ':'Aktiviraj email'}</button><div className="owner-ai-usage"><div><span>Na čekanju</span><strong>{queued.length}</strong><small>poruka u Outbox-u</small></div><div><span>Neuspešno</span><strong>{failedOutbox.length}</strong><small>poruka za retry</small></div></div><div className="owner-email-actions"><button className="primary" onClick={dispatchEmails} disabled={working||!emailConfigured||!settings?.email_from}><Mail size={15}/> Pošalji Outbox</button>{failedOutbox.length>0&&<button className="secondary" onClick={retryFailedEmails} disabled={working}><RefreshCw size={15}/> Vrati failed u red</button>}</div></section>
      <section className="admin-panel"><Head e="META PROVIDER" t="Facebook + Instagram"/><div className={`owner-ai-status ${metaConfigured?'ready':''}`}><span><Facebook size={23}/></span><div><strong>{metaConfigured?'Meta App je podešen':'Meta App nije podešen'}</strong><small>{metaConfigured?'App ID i App Secret su u Vault-u. Restorani mogu da pokrenu OAuth Connect.':'Unesi Meta App ID i App Secret. Vrednosti se čuvaju samo server-side u Supabase Vault-u.'}</small></div></div><label className="owner-ai-key">Meta App ID<input inputMode="numeric" autoComplete="off" value={metaAppId} onChange={e=>setMetaAppId(e.target.value.replace(/\D/g,''))} placeholder={metaConfigured?'Novi App ID samo ako menjaš postojeći':'npr. 123456789...'}/></label><label className="owner-ai-key">Meta App Secret<input type="password" autoComplete="new-password" value={metaAppSecret} onChange={e=>setMetaAppSecret(e.target.value)} placeholder={metaConfigured?'Novi secret samo ako menjaš postojeći':'Meta App Secret'}/></label><button className="secondary full" onClick={saveMetaProvider} disabled={working||!metaAppId.trim()||!metaAppSecret.trim()}><KeyRound size={15}/>{metaConfigured?'Promeni Meta kredencijale':'Aktiviraj Meta Connect'}</button><div className="meta-owner-setup"><span>OAUTH CALLBACK URL</span><div><code>https://pkbsveezmjkvfuiplrqb.supabase.co/functions/v1/meta-publisher?mode=callback</code><button type="button" onClick={()=>copy('https://pkbsveezmjkvfuiplrqb.supabase.co/functions/v1/meta-publisher?mode=callback')}><Copy size={13}/> Kopiraj</button></div><small>Meta permissions: pages_show_list · pages_read_engagement · pages_manage_posts · read_insights · instagram_basic · instagram_content_publish · instagram_manage_insights</small></div><div className="meta-owner-note"><ShieldCheck size={15}/><span>Page/Instagram tokeni se čuvaju u Vault-u po restoranu i nikada se ne šalju browseru.</span></div></section><section className="admin-panel"><Head e="STRIPE PROVIDER" t="Kartično plaćanje"/><div className={`owner-ai-status ${stripeConfigured?'ready':''}`}><span><CreditCard size={23}/></span><div><strong>{stripeConfigured?`Stripe Checkout je podešen · ${stripeMode.toUpperCase()}`:'Stripe nije podešen'}</strong><small>{stripeConfigured?(stripeMode==='test'?'TEST mode je aktivan — bez stvarne naplate. Ne puštaj kartice kupcima dok ne uneseš live ključ.':settings?.allow_card?'LIVE kartično plaćanje je uključeno kupcima.':'LIVE provider je spreman. U „Prodavac i naplata“ uključi Kartica kada želiš da ga pustiš kupcima.'):'Unesi Secret Key i Webhook Signing Secret. Obe vrednosti ostaju u Vault-u.'}</small></div></div><label className="owner-ai-key">Stripe Secret Key<input type="password" autoComplete="new-password" value={stripeSecretKey} onChange={e=>setStripeSecretKey(e.target.value)} placeholder={stripeConfigured?'Novi sk_test_… / sk_live_… samo ako menjaš':'sk_test_… ili sk_live_…'}/></label><label className="owner-ai-key">Stripe Webhook Secret<input type="password" autoComplete="new-password" value={stripeWebhookSecret} onChange={e=>setStripeWebhookSecret(e.target.value)} placeholder={stripeConfigured?'Novi whsec_… samo ako menjaš':'whsec_…'}/></label><button className="secondary full" onClick={saveStripeProvider} disabled={working||!stripeSecretKey.trim()||!stripeWebhookSecret.trim()}><KeyRound size={15}/>{stripeConfigured?'Promeni Stripe kredencijale':'Aktiviraj Stripe Checkout'}</button><div className="meta-owner-setup"><span>STRIPE WEBHOOK URL</span><div><code>https://pkbsveezmjkvfuiplrqb.supabase.co/functions/v1/stripe-webhook</code><button type="button" onClick={()=>copy('https://pkbsveezmjkvfuiplrqb.supabase.co/functions/v1/stripe-webhook')}><Copy size={13}/> Kopiraj</button></div><small>Webhook eventi: checkout.session.completed · checkout.session.async_payment_succeeded · checkout.session.async_payment_failed · checkout.session.expired</small></div><div className="meta-owner-note"><ShieldCheck size={15}/><span>Checkout je Stripe-hosted. Restaurant Autopilot ne prima niti čuva broj kartice, CVC ili podatke platne kartice.</span></div></section>
      <section className="admin-panel"><Head e="DISCOVERY BANK" t="Google Trends + učenje iz sopstvenih rezultata"/><div className={`owner-ai-status ${discoveryHealth&&discoveryHealth.stale_30d===0?'ready':''}`}><span><Search size={23}/></span><div><strong>{discoveryHealth?`${discoveryHealth.active_terms} aktivnih termina`:'Čitam Discovery Bank'}</strong><small>{discoveryHealth?.external_latest_at?`Google Trends sync: ${new Date(discoveryHealth.external_latest_at).toLocaleString('sr-RS')}.`:discoveryHealth?.last_learned_at?`Learning preračunat: ${new Date(discoveryHealth.last_learned_at).toLocaleString('sr-RS')}.`:discoveryHealth?.latest_verified_at?`Bank verifikovan: ${new Date(discoveryHealth.latest_verified_at).toLocaleString('sr-RS')}.`:'Još nema verifikovanog vremena.'}</small></div></div><div className="owner-ai-usage"><div><span>Instagram</span><strong>{discoveryHealth?.platforms?.instagram||0}</strong><small>aktivnih termina</small></div><div><span>Facebook</span><strong>{discoveryHealth?.platforms?.facebook||0}</strong><small>aktivnih termina</small></div></div><div className="owner-ai-usage"><div><span>Naučeni termini</span><strong>{discoveryHealth?.learned_terms||0}</strong><small>{discoveryHealth?.learning_samples||0} term-observacija</small></div><div><span>Google Trends</span><strong>{discoveryHealth?.external_terms||0}</strong><small>{discoveryHealth?.external_provider_configured?'provider aktivan':'provider nije podešen'}</small></div></div><label className="owner-ai-key">SerpApi ključ za Google Trends<input type="password" autoComplete="new-password" value={discoveryProviderKey} onChange={e=>setDiscoveryProviderKey(e.target.value)} placeholder={discoveryHealth?.external_provider_configured?'Novi ključ samo ako menjaš postojeći':'SerpApi API key'}/></label><button className="secondary full" onClick={()=>void saveDiscoveryProvider()} disabled={working||discoveryProviderKey.trim().length<20}><KeyRound size={15}/>{discoveryHealth?.external_provider_configured?'Promeni Trends ključ':'Aktiviraj Google Trends'}</button><div className="owner-email-actions"><button className="secondary" onClick={()=>void refreshDiscoveryLearning()} disabled={working}><RefreshCw size={15}/> Learning sada</button><button className="primary" onClick={()=>void syncExternalDiscovery()} disabled={working||!discoveryHealth?.external_provider_configured}><RefreshCw size={15}/> Trends sync sada</button></div><div className="meta-owner-note"><ShieldCheck size={15}/><span>Discovery rangiranje sada može da kombinuje tri signala: kurirani početni bank, Google Trends interes i stvarni performance objava. SerpApi ključ ostaje samo u Supabase Vault-u.</span></div></section><section className="admin-panel stripe-event-panel"><Head e="DISCOVERY SYNC HISTORY" t="Poslednji learning i trend runovi"/><div className="stripe-event-list">{discoveryRuns.length?discoveryRuns.map(run=><article className={`stripe-event-row ${run.status==='failed'?'failed':run.status==='success'?'processed':'received'}`} key={run.id}><span className="stripe-event-dot"/><div><strong>{run.mode==='performance_learning'?'Performance learning':run.mode==='external_ingest'?'Google Trends sync':run.source}</strong><small>{run.source} · {run.terms_updated}/{run.terms_seen} termina</small>{run.error_message&&<p>{run.error_message}</p>}</div><span className={`stripe-event-status ${run.status==='success'?'processed':run.status==='failed'?'failed':'received'}`}>{run.status}</span><time>{new Date(run.started_at).toLocaleString('sr-RS')}</time></article>):<div className="admin-empty">Još nema zabeleženih Discovery runova.</div>}</div></section><section className="admin-panel stripe-event-panel"><Head e="RISING TREND CANDIDATES" t="Novi Google Trends upiti čekaju tvoju odluku" side={<span className="admin-counter">{discoveryCandidates.filter(x=>x.status==='pending').length} čeka</span>}/><div className="stripe-event-list">{discoveryCandidates.length?discoveryCandidates.map(item=><article className={'stripe-event-row '+(item.status==='rejected'?'failed':item.status==='approved'?'processed':'received')} key={item.id}><span className="stripe-event-dot"/><div><strong>{item.query}</strong><small>{item.trend_type.toUpperCase()} · seed: {item.seed_query} · {item.geo||'WORLD'} · relevance {item.relevance_score}/100</small><p>{item.trend_value||String(item.extracted_value)}{item.extracted_value>0?' · signal '+item.extracted_value:''}</p></div><span className={'stripe-event-status '+(item.status==='approved'?'processed':item.status==='rejected'?'failed':'received')}>{item.status}</span><div className="order-admin-actions">{item.status==='pending'?<><button className="paid-button" disabled={working} onClick={()=>void decideDiscoveryCandidate(item,'approved')}>Odobri</button><button className="danger-soft" disabled={working} onClick={()=>void decideDiscoveryCandidate(item,'rejected')}>Odbij</button></>:<button className="secondary" disabled={working} onClick={()=>void decideDiscoveryCandidate(item,'pending')}>Vrati</button>}</div></article>):<div className="admin-empty">Nema rising kandidata. Pojaviće se posle Google Trends sync-a kada provider bude aktivan.</div>}</div></section>
      {settings&&<section className="admin-panel owner-sales-settings"><Head e="PRODAVAC I NAPLATA" t="Podaci koji idu kupcu"/><div className="admin-form-grid"><F l="Naziv u aplikaciji" v={settings.company_name} c={v=>setSettings({...settings,company_name:v})}/><F l="Pravni naziv" v={settings.legal_name||''} c={v=>setSettings({...settings,legal_name:v})}/><F l="PIB" v={settings.tax_id||''} c={v=>setSettings({...settings,tax_id:v})}/><F l="Matični broj" v={settings.company_number||''} c={v=>setSettings({...settings,company_number:v})}/><F l="Adresa" v={settings.address||''} c={v=>setSettings({...settings,address:v})}/><F l="Sales email" v={settings.sales_email||''} c={v=>setSettings({...settings,sales_email:v})}/><F l="Support email" v={settings.support_email||''} c={v=>setSettings({...settings,support_email:v})}/><F l="Email from (verifikovan domen)" v={settings.email_from||''} c={v=>setSettings({...settings,email_from:v})}/><F l="Naziv pošiljaoca" v={settings.email_sender_name||'Restaurant Autopilot'} c={v=>setSettings({...settings,email_sender_name:v})}/><F l="Banka" v={settings.bank_name||''} c={v=>setSettings({...settings,bank_name:v})}/><F l="Broj računa" v={settings.bank_account||''} c={v=>setSettings({...settings,bank_account:v})}/><F l="Model" v={settings.payment_model||''} c={v=>setSettings({...settings,payment_model:v})}/><F l="PayPal link" v={settings.paypal_url||''} c={v=>setSettings({...settings,paypal_url:v})}/><F l="Uslovi korišćenja URL" v={settings.terms_url||''} c={v=>setSettings({...settings,terms_url:v})}/><F l="Politika privatnosti URL" v={settings.privacy_url||''} c={v=>setSettings({...settings,privacy_url:v})}/><label className="span-2">Instrukcije za uplatu<textarea rows={4} value={settings.bank_instructions||''} onChange={e=>setSettings({...settings,bank_instructions:e.target.value})}/></label><div className="sales-method-toggles span-2"><SmallToggle l="Uplata na račun" v={settings.allow_bank_transfer} c={v=>setSettings({...settings,allow_bank_transfer:v})}/><SmallToggle l="Faktura" v={settings.allow_invoice} c={v=>setSettings({...settings,allow_invoice:v})}/><SmallToggle l="PayPal" v={settings.allow_paypal} c={v=>setSettings({...settings,allow_paypal:v})}/><SmallToggle l="Kartica" v={settings.allow_card} c={v=>setSettings({...settings,allow_card:v})}/><SmallToggle l="Trial" v={settings.trial_enabled} c={v=>setSettings({...settings,trial_enabled:v})}/></div></div><button className="primary" onClick={saveSales} disabled={working}><Save size={16}/> Sačuvaj prodaju</button></section>}
    </div>}

    {view==='messages'&&<section className="admin-panel"><Head e="EMAIL / IN-APP OUTBOX" t="Sistemske i ručne poruke" side={<div className="admin-head-actions"><span className="admin-counter">{queued.length} čeka</span><button className="secondary" onClick={dispatchEmails} disabled={working||!emailConfigured||!settings?.email_from}><Mail size={14}/> Pošalji red</button>{failedOutbox.length>0&&<button className="secondary" onClick={retryFailedEmails} disabled={working}><RefreshCw size={14}/> Retry {failedOutbox.length}</button>}</div>}/><div className="outbox-list">{outbox.length?outbox.map(x=><div className={`outbox-row ${x.delivery_status}`} key={x.id}><div><strong>{x.subject}</strong><span>{x.recipient_email||'bez emaila'} · {new Date(x.created_at).toLocaleString('sr-RS')}</span><p>{x.body}</p></div><span className={`status ${x.delivery_status}`}>{x.delivery_status}</span><div className="admin-row-actions"><button onClick={()=>copy(`${x.subject}\n\n${x.body}`)}><Copy size={13}/> Kopiraj</button>{x.delivery_status==='queued'&&<><button onClick={()=>void markOut(x,'sent')}><CheckCircle2 size={13}/> Poslato</button><button className="danger-soft" onClick={()=>void markOut(x,'dismissed')}>Skloni</button></>}</div></div>):<div className="admin-empty">Outbox je prazan.</div>}</div></section>}

    {view==='audit'&&<section className="admin-panel"><Head e="AUDIT LOG" t="Koja OWNER akcija je urađena i kada"/><div className="audit-list">{audit.length?audit.map(x=><div className="audit-row" key={x.id}><span className="audit-dot"/><div><strong>{auditLabel(x.action)}</strong><span>{x.entity_type}{x.entity_id?` · ${x.entity_id}`:''}</span></div><code>{compact(x.details)}</code><time>{new Date(x.created_at).toLocaleString('sr-RS')}</time></div>):<div className="admin-empty">Audit je prazan.</div>}</div></section>}

    {detailTarget&&<div className="modal-backdrop" onMouseDown={()=>setDetailTarget(null)}><div className="modal-card customer-detail-modal" onMouseDown={e=>e.stopPropagation()}><div className="modal-head"><div><p className="eyebrow">KUPAC · 360° PREGLED</p><h2>{detailTarget.full_name||detailTarget.email}</h2><p className="muted">{detailTarget.email}{detailTarget.company?` · ${detailTarget.company}`:''}</p></div><button className="icon-button" onClick={()=>setDetailTarget(null)}>×</button></div><div className="customer-detail-kpis"><div><span>Paket</span><strong>{detailSub?.sales_plans?.name||'Bez paketa'}</strong><small>{detailSub?.status||'—'}</small></div><div><span>Lokacije</span><strong>{detailRestaurants.length}</strong><small>{detailRestaurants.map(x=>x.name).join(' · ')||'Nema restorana'}</small></div><div><span>Objave</span><strong>{detailPosts}</strong><small>ukupno kreirano</small></div><div><span>AI slike</span><strong>{detailAi}</strong><small>sačuvani asseti</small></div><div><span>Naplaćeno</span><strong>{detailPaid.toFixed(0)} €</strong><small>{detailOrders.filter(x=>x.status==='paid').length} plaćenih naloga</small></div><div><span>Važi do</span><strong>{detailSub?.expires_at?new Date(detailSub.expires_at).toLocaleDateString('sr-RS'):'—'}</strong><small>{detailSub?.expires_at?`još ${Math.max(0,daysTo(detailSub.expires_at))} dana`:'bez roka / nema paketa'}</small></div></div><div className="customer-detail-sections"><section><h3>Kontakt / firma</h3><p>{detailTarget.phone||'Telefon nije unet'}</p><p>{detailTarget.company||'Firma nije uneta'}</p><p>{detailTarget.billing_city||''} {detailTarget.billing_country||''}</p></section><section><h3>Restorani</h3>{detailRestaurants.length?detailRestaurants.map(x=><p key={x.id}><b>{x.name}</b>{x.city?` · ${x.city}`:''}</p>):<p>Nema dodatih restorana.</p>}</section><section><h3>Prodaja</h3>{detailOrders.slice(0,6).map(o=><p key={o.id}><b>{o.order_number}</b> · {o.status} · {Number(o.amount).toFixed(0)} {o.currency}</p>)}{!detailOrders.length&&<p>Nema narudžbina.</p>}</section></div><div className="modal-actions"><button className="secondary" onClick={()=>{setNoteTarget(detailTarget);setNoteBody('');setDetailTarget(null)}}><Mail size={15}/> Pošalji poruku</button><button className="primary" onClick={()=>setDetailTarget(null)}>Zatvori</button></div></div></div>}
    {noteTarget&&<div className="modal-backdrop" onMouseDown={()=>setNoteTarget(null)}><div className="modal-card admin-note-modal" onMouseDown={e=>e.stopPropagation()}><p className="eyebrow">PORUKA KUPCU</p><h2>{noteTarget.email}</h2><label>Naslov<input value={noteSubject} onChange={e=>setNoteSubject(e.target.value)}/></label><label>Poruka<textarea rows={6} value={noteBody} onChange={e=>setNoteBody(e.target.value)}/></label><div className="modal-actions"><button className="secondary" onClick={()=>setNoteTarget(null)}>Otkaži</button><button className="primary" onClick={sendNote} disabled={working}><Mail size={15}/> Dodaj poruku</button></div></div></div>}
  </div>
}

function Tab({a,f,i,l,c}:{a:boolean;f:()=>void;i:ReactNode;l:string;c?:number}){return <button className={a?'active':''} onClick={f}>{i}{l}{c?<b>{c}</b>:null}</button>}
function Metric({i,l,v}:{i:ReactNode;l:string;v:string|number}){return <div className="admin-metric"><span>{i}</span><div><small>{l}</small><strong>{v}</strong></div></div>}
function Head({e,t,side}:{e:string;t:string;side?:ReactNode}){return <div className="admin-panel-head"><div><p className="eyebrow">{e}</p><h2>{t}</h2></div>{side}</div>}
function HealthCard({icon,title,value,detail,ok}:{icon:ReactNode;title:string;value:string;detail:string;ok:boolean}){return <div className={`owner-health ${ok?'ok':''}`}><span>{icon}</span><div><small>{title}</small><strong>{value}</strong><p>{detail}</p></div><i/></div>}
function BigToggle({icon,title,detail,value,onChange,danger=false}:{icon:ReactNode;title:string;detail:string;value:boolean;onChange:(v:boolean)=>void;danger?:boolean}){return <button type="button" className={`owner-big-toggle ${value?'on':''} ${danger?'danger-mode':''}`} onClick={()=>onChange(!value)}><span>{icon}</span><div><strong>{title}</strong><small>{detail}</small></div><b>{value?<Eye size={15}/>:<EyeOff size={15}/>} {value?'UKLJUČENO':'ISKLJUČENO'}</b></button>}
function F({l,v,c}:{l:string;v:string;c:(v:string)=>void}){return <label>{l}<input value={v} onChange={e=>c(e.target.value)}/></label>}
function SmallToggle({l,v,c}:{l:string;v:boolean;c:(v:boolean)=>void}){return <label className={`sales-toggle ${v?'on':''}`}><input type="checkbox" checked={v} onChange={e=>c(e.target.checked)}/><span/><b>{l}</b></label>}

function QuickSale({profiles,plans,form,setForm,go,working}:{profiles:CustomerProfile[];plans:SalesPlan[];form:SaleForm;setForm:(v:SaleForm)=>void;go:()=>void;working:boolean}){return <section className="admin-panel"><Head e="BRZA PRODAJA" t="Aktiviraj kupca odmah"/><div className="admin-form-grid"><label>Kupac<select value={form.userId} onChange={e=>setForm({...form,userId:e.target.value})}><option value="">Izaberi</option>{profiles.map(p=><option key={p.user_id} value={p.user_id}>{p.email}</option>)}</select></label><label>Paket<select value={form.planId} onChange={e=>setForm({...form,planId:e.target.value})}><option value="">Izaberi</option>{plans.filter(p=>p.active).map(p=><option key={p.id} value={p.id}>{p.name} · {p.price} {p.currency}</option>)}</select></label><label>Dana<input type="number" min="1" value={form.days} onChange={e=>setForm({...form,days:e.target.value})}/></label><label>Naplaćeno<input type="number" min="0" step="0.01" value={form.amount} onChange={e=>setForm({...form,amount:e.target.value})}/></label><label>Način<select value={form.paymentMethod} onChange={e=>setForm({...form,paymentMethod:e.target.value})}>{methods.map(([k,l])=><option key={k} value={k}>{l}</option>)}</select></label><label>Napomena<input value={form.note} onChange={e=>setForm({...form,note:e.target.value})}/></label></div><button className="primary full" onClick={go} disabled={working}><CheckCircle2 size={16}/> Aktiviraj i evidentiraj</button></section>}
function LicenseMaker({plans,form,setForm,go,generated,copy,working}:{plans:SalesPlan[];form:LicenseForm;setForm:(v:LicenseForm)=>void;go:()=>void;generated:Generated|null;copy:(v:string)=>void;working:boolean}){return <section className="admin-panel"><Head e="AKTIVACIONI KOD" t="Prodaj licencu"/><div className="admin-form-grid"><label>Paket<select value={form.planId} onChange={e=>setForm({...form,planId:e.target.value})}><option value="">Izaberi</option>{plans.filter(p=>p.active).map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label><label>Email<input value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></label><label>Dana<input type="number" min="1" value={form.days} onChange={e=>setForm({...form,days:e.target.value})}/></label><label>Cena<input type="number" min="0" step="0.01" value={form.amount} onChange={e=>setForm({...form,amount:e.target.value})}/></label><label>Način<select value={form.paymentMethod} onChange={e=>setForm({...form,paymentMethod:e.target.value})}>{methods.map(([k,l])=><option key={k} value={k}>{l}</option>)}</select></label><label>Napomena<input value={form.note} onChange={e=>setForm({...form,note:e.target.value})}/></label></div><button className="primary full" onClick={go} disabled={working}><KeyRound size={16}/> Generiši licencu</button>{generated&&<div className="generated-license"><span>KOPIRAJ SADA</span><strong>{generated.code}</strong><small>{generated.plan}</small><button onClick={()=>copy(generated.code)}><Copy size={15}/> Kopiraj</button></div>}</section>}
function Orders({rows,profiles,paid,cancel,refund,working}:{rows:SalesOrder[];profiles:CustomerProfile[];paid:(o:SalesOrder)=>void;cancel:(o:SalesOrder)=>void;refund:(o:SalesOrder)=>void;working:boolean}){const map=new Map(profiles.map(p=>[p.user_id,p]));return <div className="admin-table orders-table orders-table-v2"><div className="admin-table-head"><span>Narudžbina</span><span>Kupac</span><span>Paket</span><span>Iznos</span><span>Status</span><span>Akcija</span></div>{rows.length?rows.map(o=><div className="admin-table-row" key={o.id}><div><strong>{o.order_number}</strong><small>{new Date(o.created_at).toLocaleString('sr-RS')} · {o.payment_reference||o.order_number}</small></div><div><strong>{map.get(o.user_id)?.email||'Kupac'}</strong><small>{o.payment_method}{o.payment_provider?` · ${o.payment_provider}`:''}{o.provider_payment_status?` · ${o.provider_payment_status}`:''}</small>{o.provider_checkout_session_id&&<small className="stripe-order-ref">session · {o.provider_checkout_session_id.slice(0,12)}…</small>}{o.provider_payment_intent_id&&<small className="stripe-order-ref">payment · {o.provider_payment_intent_id.slice(0,12)}…</small>}</div><div><strong>{o.sales_plans?.name||'—'}</strong><small>{o.due_at?`rok ${new Date(o.due_at).toLocaleDateString('sr-RS')}`:''}</small></div><strong>{o.amount} {o.currency}</strong><span className={`status ${o.status}`}>{o.status}</span><div className="order-admin-actions">{o.status==='pending'&&<><button className="paid-button" disabled={working} onClick={()=>paid(o)}>Uplata primljena</button><button className="danger-soft" onClick={()=>cancel(o)}>Otkaži</button></>}{o.status==='paid'&&<button className="refund-button" onClick={()=>refund(o)}>Refund</button>}</div></div>):<div className="admin-empty">Nema narudžbina.</div>}</div>}
function PlanEditor({plan,onSave}:{plan:SalesPlan;onSave:(p:SalesPlan,patch:{price:number;monthly_generation_limit:number;max_restaurants:number;trial_days:number;active:boolean;public:boolean;features:Record<string,unknown>})=>void}){
  const [price,setPrice]=useState(Number(plan.price)),[limit,setLimit]=useState(plan.monthly_generation_limit),[max,setMax]=useState(plan.max_restaurants),[trial,setTrial]=useState(plan.trial_days)
  const [ai,setAi]=useState(Number(plan.features?.ai_images_monthly||0)),[weekly,setWeekly]=useState(Number(plan.features?.weekly_posts||5)),[campaigns,setCampaigns]=useState(Boolean(plan.features?.campaigns)),[pack,setPack]=useState(Boolean(plan.features?.campaign_pack)),[active,setActive]=useState(plan.active),[isPublic,setPublic]=useState(plan.public)
  useEffect(()=>{setPrice(Number(plan.price));setLimit(plan.monthly_generation_limit);setMax(plan.max_restaurants);setTrial(plan.trial_days);setAi(Number(plan.features?.ai_images_monthly||0));setWeekly(Number(plan.features?.weekly_posts||5));setCampaigns(Boolean(plan.features?.campaigns));setPack(Boolean(plan.features?.campaign_pack));setActive(plan.active);setPublic(plan.public)},[plan])
  const save=()=>onSave(plan,{price,monthly_generation_limit:limit,max_restaurants:max,trial_days:trial,active,public:isPublic,features:{...plan.features,ai_images_monthly:ai,weekly_posts:weekly,campaigns,campaign_pack:pack,creative_advisor:true,template_library:true,visual_studio:true,publish_center:true,brand_kit:true}})
  return <article className={`owner-plan-card ${active?'':'disabled'}`}><div className="owner-plan-head"><div><span>{plan.billing_interval}</span><b>{plan.code}</b></div><div><button className={active?'on':''} onClick={()=>setActive(!active)}>{active?'AKTIVAN':'UGAŠEN'}</button><button className={isPublic?'on':''} onClick={()=>setPublic(!isPublic)}>{isPublic?'JAVAN':'SKRIVEN'}</button></div></div><h3>{plan.name}</h3><p>{plan.description}</p><div className="owner-plan-fields"><label>Cena<input type="number" min="0" step="0.01" value={price} onChange={e=>setPrice(Number(e.target.value))}/></label><label>Objava/mes<input type="number" min="0" value={limit} onChange={e=>setLimit(Number(e.target.value))}/></label><label>Restorana<input type="number" min="1" value={max} onChange={e=>setMax(Number(e.target.value))}/></label><label>Trial dana<input type="number" min="0" max="90" value={trial} onChange={e=>setTrial(Number(e.target.value))}/></label><label>AI slika/mes<input type="number" min="0" value={ai} onChange={e=>setAi(Number(e.target.value))}/></label><label>Objava/nedelja<input type="number" min="1" max="14" value={weekly} onChange={e=>setWeekly(Number(e.target.value))}/></label></div><div className="owner-feature-toggles"><SmallToggle l="Campaigns" v={campaigns} c={setCampaigns}/><SmallToggle l="Campaign Pack" v={pack} c={setPack}/></div><button className="primary full" onClick={save}><Save size={14}/> Sačuvaj paket</button></article>
}
function daysTo(v:string){return Math.ceil((new Date(v).getTime()-Date.now())/86400000)}
function sameMonth(value:string,date:Date){const d=new Date(value);return d.getMonth()===date.getMonth()&&d.getFullYear()===date.getFullYear()}
function auditLabel(v:string){return({order_paid:'Uplata potvrđena',order_refunded:'Refund',access_granted:'Ručna aktivacija',license_created:'Licenca kreirana',license_redeemed:'Licenca aktivirana',trial_started:'Trial',customer_note_queued:'Poruka kupcu',housekeeping:'Housekeeping',ai_provider_key_updated:'AI ključ promenjen',meta_provider_updated:'Meta provider promenjen',stripe_provider_updated:'Stripe provider promenjen',discovery_provider_updated:'Discovery provider promenjen',discovery_candidate_approved:'Trend kandidat odobren',discovery_candidate_rejected:'Trend kandidat odbijen',discovery_candidate_reset:'Trend kandidat vraćen'} as Record<string,string>)[v]||v}
function compact(v:Record<string,unknown>){const s=JSON.stringify(v);return s.length>120?`${s.slice(0,117)}…`:s}
function downloadCsv(name:string,rows:string[][]){const q=(v:string)=>`"${String(v).replaceAll('"','""')}"`;downloadText(name,'\ufeff'+rows.map(r=>r.map(q).join(';')).join('\n'),'text/csv;charset=utf-8')}
function downloadText(name:string,text:string,type:string){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
